arguments.command:
set -e
cat > /etc/nginx/sites-available/deploy.conf <<'EOF'
server {
    listen 8443 ssl;
    server_name localhost;

    ssl_certificate     /etc/nginx/ssl/self.crt;
    ssl_certificate_key /etc/nginx/ssl/self.key;

    root /var/www/deploy/main;
    index index.html;

    location /dev/ {
        alias /var/www/deploy/dev/;
        index index.html;
    }

    location / {
        try_files $uri $uri/ =404;
    }
}
EOF
ln -sf /etc/nginx/sites-available/deploy.conf /etc/nginx/sites-enabled/deploy.conf
rm -f /etc/nginx/sites-enabled/default

cat > /git/project/hooks/post-receive <<'EOF'
#!/bin/bash
GIT_DIR=/git/project
export GIT_DIR
while read oldrev newrev refname; do
    branch=$(basename "$refname")
    if [ "$branch" = "main" ]; then
        git --work-tree=/var/www/deploy/main --git-dir=$GIT_DIR checkout -f main
    elif [ "$branch" = "dev" ]; then
        git --work-tree=/var/www/deploy/dev --git-dir=$GIT_DIR checkout -f dev
    fi
done
EOF
chmod +x /git/project/hooks/post-receive
chown -R git:git /git /var/www/deploy
echo OK

